<?php require_once __DIR__.'/../includes/auth.php'; require_role('DONOR');
$d=my_donor($pdo); $id=(int)$d['donor_id'];
$one=function($sql,$p)use($pdo){$s=$pdo->prepare($sql);$s->execute($p);return $s;};
$total=(int)$one("SELECT COALESCE(SUM(units_donated),0) FROM donations WHERE donor_id=? AND status='COMPLETED'",[$id])->fetchColumn();
$pending=(int)$one("SELECT COUNT(*) FROM donor_matches m JOIN emergency_requests r USING(request_id) WHERE m.donor_id=? AND m.status='NOTIFIED' AND r.status IN ('PENDING','MATCHING','PARTIALLY_FULFILLED') AND r.required_time>=NOW()",[$id])->fetchColumn();
$accepted=(int)$one("SELECT COUNT(*) FROM donor_matches m JOIN emergency_requests r USING(request_id) WHERE m.donor_id=? AND m.status='ACCEPTED' AND r.status IN ('PENDING','MATCHING','PARTIALLY_FULFILLED')",[$id])->fetchColumn();
$unread=(int)$one('SELECT COUNT(*) FROM notifications WHERE user_id=? AND is_read=0',[$_SESSION['uid']])->fetchColumn();
$notices=$one('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 5',[$_SESSION['uid']])->fetchAll();
$checkup=$one("SELECT c.*,o.organization_name,o.address,o.city,o.phone FROM donor_checkups c JOIN healthcare_organizations o ON o.organization_id=c.organization_id WHERE c.donor_id=? AND c.outcome='PENDING' ORDER BY c.scheduled_date LIMIT 1",[$id])->fetch();
$anyCheckup=(int)$one('SELECT COUNT(*) FROM donor_checkups WHERE donor_id=?',[$id])->fetchColumn();
$waiting=$one("SELECT m.match_id,r.blood_group,r.urgency,r.required_time,r.location,o.organization_name FROM donor_matches m JOIN emergency_requests r ON r.request_id=m.request_id JOIN healthcare_organizations o ON o.organization_id=r.organization_id WHERE m.donor_id=? AND m.status='NOTIFIED' AND r.status IN ('PENDING','MATCHING','PARTIALLY_FULFILLED') AND r.required_time>=NOW() ORDER BY FIELD(r.urgency,'CRITICAL','HIGH','NORMAL'),r.required_time LIMIT 3",[$id])->fetchAll();
$camps=$one("SELECT c.campaign_name,c.campaign_date,c.location,o.organization_name FROM donation_campaigns c JOIN healthcare_organizations o ON o.organization_id=c.organization_id WHERE c.status IN ('UPCOMING','ACTIVE') AND c.campaign_date>=CURDATE() ORDER BY c.campaign_date LIMIT 3",[])->fetchAll();
$regs=$one("SELECT c.campaign_name,c.campaign_date,c.location FROM donor_campaign_registrations r JOIN donation_campaigns c ON c.campaign_id=r.campaign_id WHERE r.donor_id=? AND r.status='REGISTERED' AND c.campaign_date>=CURDATE() AND c.status IN ('UPCOMING','ACTIVE') ORDER BY c.campaign_date LIMIT 3",[$id])->fetchAll();
$next=donor_next_eligible_date($d['last_donation_date']); $intervalOk=!$next||$next<=date('Y-m-d');
$steps=[['Registered',true],['Checkup scheduled',$anyCheckup>0],['Health cleared',$d['health_status']==='CLEARED'],['Verified by administrator',$d['verification_status']==='VERIFIED']];
$title='Donor Dashboard'; $page_intro='Your donations, eligibility and recent notifications.'; require '../includes/header.php'; ?>
<?php
$ch=function($ic,$col,$t){ return '<div class="ch"><span class="ci '.$col.'">'.icon($ic).'</span><h2>'.h($t).'</h2></div>'; };
$es=function($ic,$t,$t2=''){ return '<div class="es"><span class="ci">'.icon($ic).'</span><div><span>'.h($t).'</span>'.($t2?'<small>'.h($t2).'</small>':'').'</div></div>'; };
$stepSub=['Completed',$anyCheckup>0?'Done':'Pending',$d['health_status']==='CLEARED'?'Done':'Pending',$d['verification_status']==='VERIFIED'?'Done':'Pending'];
$stepIc=['check','calendar','heart','user'];
$nmsg=function($x){ return $x['notification_type']==='WELCOME' ? 'Your donor account has been created and is pending administrator review. Next, the administrator will schedule your health checkup and you will be notified here.' : $x['message']; };
$ndate=function($t){ return date('d M Y, g:i A',strtotime($t)); };
?>
<?php if($d['verification_status']!=='VERIFIED' || $d['health_status']!=='CLEARED'): ?><div class="alert">Your account is not yet fully cleared for matching. Verification: <b><?= h($d['verification_status']) ?></b>; health status: <b><?= h($d['health_status']) ?></b>. <a href="verification-status.php">View your verification progress</a>.</div><?php endif; ?>
<div class="card wc"><span class="ci red"><?= icon('heart') ?></span><div><h2>Welcome back, <?= h(explode(' ',trim($d['full_name']))[0]) ?>!</h2><p>Your donation makes a difference. Together, we save lives.</p></div><div class="wc-act"><a class="btn" href="emergency_requests.php">View requests <?= icon('arrow') ?></a><a class="btn alt" href="campaigns.php">Explore campaigns</a></div></div>
<div class="card vp"><div class="vp-head"><span class="ci navy"><?= icon('shield') ?></span><div><h2>Verification progress</h2><span class="muted">Complete all steps to become a verified donor.</span></div></div>
<ol class="vsteps"><?php foreach($steps as $i=>$st): ?><li class="<?= $st[1]?'done':'' ?>"><span class="vc"><?= icon($st[1]?'check':$stepIc[$i]) ?></span><div><b><?= ($i+1).'. '.h($st[0]) ?></b><small><?= h($stepSub[$i]) ?></small></div></li><?php endforeach; ?></ol></div>
<div class="grid stats6">
<div class="stat c-red"><span class="ci red"><?= icon('drop') ?></span><b><?= h($d['blood_group']) ?></b><span>Registered blood group</span></div>
<div class="stat c-gray"><span class="ci gray"><?= icon('ban') ?></span><b class="sm"><?= h($d['availability_status']) ?></b><span>Availability</span></div>
<div class="stat c-green"><span class="ci green"><?= icon('drop') ?></span><b><?= $total ?></b><span>Units donated</span></div>
<div class="stat c-orange"><span class="ci orange"><?= icon('clock') ?></span><b><?= $pending ?></b><span>Requests awaiting response</span></div>
<div class="stat c-blue"><span class="ci blue"><?= icon('check') ?></span><b><?= $accepted ?></b><span>Accepted open requests</span></div>
<div class="stat c-pink"><span class="ci pink"><?= icon('bell') ?></span><b><?= $unread ?></b><span>Unread notifications</span></div>
</div>
<div class="grid two"><div class="card"><?= $ch('shield','blue','Eligibility') ?><div class="elig"><span class="ci green"><?= icon('check') ?></span><p><?= $intervalOk?'<b>No donation interval pending.</b>':'<b>Next eligible date: '.h($next).'</b>' ?><br>Last donation: <?= h($d['last_donation_date']?:'not recorded') ?><br><span class="muted">A <?= DONATION_GAP_MONTHS ?>-month interval applies after each donation (NBTS rule). Final eligibility is decided by healthcare staff.</span></p></div></div>
<div class="card"><?= $ch('calendar','blue','Upcoming checkup') ?><?php if($checkup): ?><p><b><?= h($checkup['organization_name']) ?></b><br><?= h($checkup['address']?:$checkup['city']) ?><br>Phone: <?= h($checkup['phone']?:'—') ?><br>Date: <b><?= h($checkup['scheduled_date']) ?></b> <?= badge($checkup['outcome']) ?></p><a class="btn sm alt" href="appointments.php">View / request change</a><?php else: echo $es('calendar','No checkup is currently scheduled.','The administrator will assign one.'); endif; ?></div></div>
<div class="card wide"><?= $ch('clipboard','red','Requests waiting for your response') ?><div class="wide-body"><div><?php foreach($waiting as $w): ?><p><?= badge($w['urgency']) ?> <b><?= h($w['blood_group']) ?></b> at <?= h($w['location']) ?> (<?= h($w['organization_name']) ?>), needed by <?= h($w['required_time']) ?></p><?php endforeach; if(!$waiting) echo $es('clipboard','No requests waiting.'); ?></div><a class="btn" href="emergency_requests.php">View requests</a></div></div>
<div class="grid two"><div class="card"><?= $ch('megaphone','blue','My registered campaigns') ?><?php foreach($regs as $c): ?><div class="mini"><span class="ci red"><?= icon('drop') ?></span><div><b><?= h($c['campaign_name']) ?></b><small><?= h($c['campaign_date']) ?> &middot; <?= h($c['location']) ?></small></div></div><?php endforeach; if(!$regs) echo $es('megaphone','You have not registered for any upcoming campaign.'); ?><a class="btn sm alt" href="campaigns.php?view=mine">My registrations</a></div>
<div class="card"><?= $ch('calendar','blue','Upcoming campaigns') ?><?php foreach($camps as $c): ?><div class="mini"><span class="ci red"><?= icon('drop') ?></span><div><b><?= h($c['campaign_name']) ?></b><small><?= h($c['organization_name']) ?> &middot; <?= h($c['campaign_date']) ?> &middot; <?= h($c['location']) ?></small></div></div><?php endforeach; if(!$camps) echo $es('calendar','No upcoming campaigns.'); ?><a class="btn sm alt" href="campaigns.php">Browse campaigns</a></div></div>
<div class="card"><?= $ch('bell','blue','Recent notifications') ?><?php if(!$notices) echo $es('bell','No notifications yet.','Important updates will appear here.'); ?><?php foreach($notices as $x): ?><div class="notice-row<?= !$x['is_read']?' unread':'' ?>"><div class="nr-top"><b><?= h($x['title']) ?></b><?= !$x['is_read']?'<span class="badge nb">NEW</span>':'' ?></div><p><?= h($nmsg($x)) ?></p><span class="nr-time"><?= icon('clock') ?> <?= h($ndate($x['created_at'])) ?></span></div><?php endforeach; ?><div class="row-actions"><a class="btn sm" href="notifications.php">All notifications</a> <a class="btn sm alt" href="profile.php">Update profile</a></div></div>
<?php require '../includes/footer.php'; ?>
